main.css:
.ts-x-goals-html .lay { position: absolute; inset: 0; display: flex; flex-direction: column; gap: 26px; }
.ts-x-goals-html .head { display: grid; grid-template-columns: 4fr 8fr; gap: 72px; align-items: start; }
.ts-x-goals-html .head h2 { margin-bottom: 0; }
.ts-x-goals-html .head p { margin-top: 0; }
.ts-x-goals-html .plain { font-size: 20px; line-height: 1.45; }
.ts-x-goals-html .plain > span { padding: 8px 0; }
.ts-x-goals-html .plain > span > .ic { width: 20px; height: 20px; vertical-align: -4px; margin-right: 10px; }
.ts-x-goals-html .plain > span:has(> .ic) { padding-left: 30px; text-indent: -30px; }
.ts-x-goals-html .proof { display: grid; grid-template-columns: 1fr 1fr; gap: 48px; align-items: start; }
.ts-x-goals-html figure { margin: 0; display: grid; gap: 8px; }
.ts-x-goals-html figcaption { font-size: 16px; line-height: 1.45; color: var(--ink-2); }
.ts-x-goals-html .proof img { display: block; width: 100%; height: auto; border: 1px solid var(--hair); background: var(--plate); }
.ts-x-goals-html .bench use { fill: var(--ink); }
.ts-x-goals-html .term { display: flex; align-items: center; gap: 28px; padding: 14px 26px; }
.ts-x-goals-html .term svg { display: block; fill: currentColor; flex: 0 0 auto; }
.ts-x-goals-html .term span { font-size: 20px; line-height: 1; }
